function Wrapper(data) {
    const items = data.data.items;
    console.log(items);
    return (
        <div className="carouselContent">
            {items.map((item,index) => (
                <div className="carouselItem">
                    <img alt={item.caption} src={item.src} key={index}/>
                    <p className='caption bg-secondary-albedo text-transform-uppercase font-tracking-20 font-weight-300 hover-font-weight-600'><span className='font-weight-500 hover-font-weight-900'>Above:</span> {item.caption}</p>
                </div>
                    
                )
            )}
        </div>
    )
}

export default function(data) {
    return <Wrapper data={data.data}/>;
}